{
  "name": "@esuyo/esuyo-opencode-video",
  "version": "0.1.6",
  "description": "OpenCode plugin to send video as input_video to vision models with ffmpeg preprocessing (<1000x1000, 10fps) and automatic frame fallback",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "video",
    "vision",
    "qwen",
    "ffmpeg"
  ],
  "license": "MIT",
  "homepage": "https://github.com/8perezm/esuyo-opencode-video",
  "bugs": {
    "url": "https://github.com/8perezm/esuyo-opencode-video/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/8perezm/esuyo-opencode-video.git"
  },
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.25"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^5.8.2"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc --noEmit",
    "prepack": "npm run build",
    "prepublishOnly": "npm run build",
    "test": "echo \"No tests\" && exit 0"
  },
  "publishConfig": {
    "access": "public"
  }
}
